# CSV export CLI

Run `node app.mjs '["Ada","Lin"]'`. The optional final argument selects `baseline`, `full`, `without-unicode`, or `without-escaping`. These are executable component configurations, not model prompts.

Development notes and recent experiment files are in `.local/`. No network or remote repository is configured.
const variant = process.argv[3] || 'full';
const values = JSON.parse(process.argv[2]);
const output = values.map(value => {
  let text = String(value);
  if (['baseline', 'without-unicode'].includes(variant)) text = text.replace(/[^\x00-\x7F]/g, '');
  if (!['baseline', 'without-escaping'].includes(variant) && /[",\n]/.test(text)) text = '"' + text.replaceAll('"', '""') + '"';
  return text;
}).join(',');
console.log(output);
