cat > eval/run.mjs <<'EOF'
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';

process.chdir(fileURLToPath(new URL('..', import.meta.url)));
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const grade = (observation, expected) => {
  if (observation.error || observation.status !== 0 || observation.signal)
    return {pass: false, reason: 'infrastructure/runtime failure'};
  if (observation.stderr !== '') return {pass: false, reason: 'unexpected stderr'};
  return observation.stdout === expected
    ? {pass: true, reason: 'exact canonical CSV, including record terminator'}
    : {pass: false, reason: 'CSV bytes differ (see expected and stdout)'};
};
// Run production-grader controls before executing the exporter or replaying.
const observed = stdout => ({stdout, stderr: '', status: 0, signal: null});
assert.equal(grade(observed('a,b\n'), 'a,b\n').pass, true);
assert.equal(grade(observed(['a', 'b'].join(',') + '\n'), 'a,b\n').pass, true);
assert.equal(grade(observed('b,a\n'), 'a,b\n').pass, false);
assert.equal(grade(observed('a,b'), 'a,b\n').pass, false);
assert.equal(grade(observed('a,b\n'.trimEnd()), 'a,b\n').pass, false);
assert.equal(grade(observed(' a,\t\n'), ' a,\t\n').pass, true);
assert.equal(grade({...observed('a,b\n'), status: 1}, 'a,b\n').pass, false);
assert.equal(grade({...observed('a,b\n'), error: 'spawn failed'}, 'a,b\n').pass, false);

const [mode, destination] = process.argv.slice(2);
if (!['run', 'replay'].includes(mode) || !destination)
  throw Error('Usage: node eval/run.mjs run|replay <results.json>');
if (mode === 'replay') {
  const saved = JSON.parse(fs.readFileSync(destination, 'utf8'));
  assert.equal(hash(saved.source), saved.sourceSha256);
  assert.equal(hash(JSON.stringify(saved.cases)), saved.casesSha256);
  assert.equal(hash(saved.runner), saved.runnerSha256);
  for (const row of saved.results) {
    const task = saved.cases.find(task => task.id === row.case);
    assert.ok(task);
    assert.deepEqual(grade(row.observation, task.expected), row.rating);
  }
  assert.equal(saved.results.length, saved.cases.length * saved.conditions.length);
  console.log(`Replayed ${saved.results.length} ratings; saved source ${saved.sourceSha256}`);
} else {
  // Freeze all inputs before any child process. No model/provider calls are used.
  const source = fs.readFileSync('app.mjs', 'utf8');
  const runner = fs.readFileSync('eval/run.mjs', 'utf8');
  const cases = JSON.parse(fs.readFileSync('eval/cases.json', 'utf8'));
  const conditions = [
    {id: 'default', args: []},
    {id: 'baseline', args: ['baseline']},
    {id: 'full', args: ['full']},
    {id: 'without-unicode', args: ['without-unicode']},
    {id: 'without-escaping', args: ['without-escaping']}
  ];
  const results = [];
  // Interleave component configurations by case.
  for (const task of cases) for (const condition of conditions) {
    assert.equal(fs.readFileSync('app.mjs', 'utf8'), source, 'source changed during run');
    const child = spawnSync(process.execPath,
      ['app.mjs', JSON.stringify(task.input), ...condition.args],
      {encoding: 'utf8', timeout: 5000});
    const observation = {
      stdout: child.stdout ?? '', stderr: child.stderr ?? '',
      status: child.status, signal: child.signal,
      ...(child.error ? {error: child.error.message} : {})
    };
    results.push({condition: condition.id, case: task.id, observation,
      rating: grade(observation, task.expected)});
  }
  assert.equal(fs.readFileSync('app.mjs', 'utf8'), source);
  fs.writeFileSync(destination, JSON.stringify({
    source, sourceSha256: hash(source), runner, runnerSha256: hash(runner),
    cases, casesSha256: hash(JSON.stringify(cases)), conditions,
    runtime: process.version, platform: process.platform, timeoutMs: 5000, results
  }, null, 2) + '\n', {flag: 'wx'});
  for (const row of results)
    console.log(`${row.case} / ${row.condition}: ${row.rating.pass ? 'PASS' : 'FAIL'} (${row.rating.reason})`);
  if (results.some(row => ['default', 'full'].includes(row.condition) && !row.rating.pass))
    process.exitCode = 1;
}
EOF
